patch:
diff --git a/repro.js b/repro.js
new file mode 100644
index 0000000..293d854
--- /dev/null
+++ b/repro.js
@@ -0,0 +1,30 @@
+"use strict";
+
+// Repro: no-unused-expressions reports "use strict" directives when ecmaVersion is 3 (9.25.0 regression).
+const { Linter } = require("./lib/api");
+const espree = require("espree");
+
+const linter = new Linter();
+const code = "'use strict';\nfunction f() { 'use strict'; }\n";
+let failed = false;
+
+for (const ecmaVersion of [3, 5, 2015, "latest"]) {
+	const ast = espree.parse(code, { ecmaVersion });
+	const messages = linter.verify(code, {
+		languageOptions: { ecmaVersion, sourceType: "script" },
+		rules: { "no-unused-expressions": "error" },
+	});
+
+	console.log(
+		`ecmaVersion ${ecmaVersion}: Program.body[0].directive=${JSON.stringify(ast.body[0].directive)}, reports:`,
+		messages.map(m => `${m.line}:${m.column} ${m.message}`),
+	);
+	if (messages.length) {
+		failed = true;
+	}
+}
+
+if (failed) {
+	console.error("BUG: directives were reported as unused expressions");
+	process.exit(1);
+}
